from common import *
import math

save_source(__file__)
summary=read(BASE/'docs/study-summary.json')
progress=read(PROGRESS)
assert all(progress['scientific_candidates'][v]['status']=='completed' for v in ['h7q10','h15q10'])
docs={}
for h in [7,15,20]:
 for typ in ['continuous','q10']:
  name=f'h{h}{typ}'
  file=BASE/'metrics'/(name+'-new.json' if name in VARIANTS else name+'.json')
  d=read(file)
  assert set(d['pools']['all']['seeds'])==set(map(str,SEEDS))
  e=d['pools']['all']['ensemble']
  assert e['head']['3']['5']['n_days']==1448
  assert e['head_regimes']['F']['3']['5']['n_days']==136
  docs[name]=(file,e)

pairs={}
for h in [7,15,20]:
 pairs[str(h)]={}
 for regime in ['D','F','T']:
  a=docs[f'h{h}q10'][1]['head_regimes'][regime]['3']['5']
  b=docs[f'h{h}continuous'][1]['head_regimes'][regime]['3']['5']
  pairs[str(h)][regime]={}
  for k in ['net_ann','net_sharpe','net_ann_vol']:
   delta=a[k]-b[k]
   assert math.isfinite(delta)
   assert abs(delta-summary['style_pairs'][str(h)][regime][k])<1e-12
   pairs[str(h)][regime][k]={'continuous':b[k],'q10':a[k],'difference':delta}

maxima={}
for typ in ['continuous','q10']:
 maxima[typ]={}
 for regime in ['D','F','T']:
  maxima[typ][regime]={}
  for k in ['net_ann','net_sharpe']:
   values={h:docs[f'h{h}{typ}'][1]['head_regimes'][regime]['3']['5'][k] for h in [7,15,20]}
   winners=[h for h,v in values.items() if abs(v-max(values.values()))<=1e-12]
   assert winners==summary['horizon_maxima'][typ][regime][k]
   maxima[typ][regime][k]=winners

t_down=sum(pairs[str(h)]['T']['net_ann']['difference'] < -1e-12 for h in [7,15,20])
d_up=sum(pairs[str(h)]['D']['net_ann']['difference'] > 1e-12 for h in [7,15,20])
assert summary['T_return_weaker_all_three']==(t_down==3)
assert summary['D_return_stronger_all_three']==(d_up==3)
out={'verified_at':time.time(),'scope':'Completed H7/H15 new q10 plus frozen same-source H20 q10; independent JSON arithmetic verification, not a new fit or alternative metric evaluation.',
 'evidence':[fingerprint(p) for p,e in docs.values()], 'paired_style_metrics':pairs,'horizon_maxima':maxima,
 'T_return_decreased_horizons':t_down,'D_return_increased_horizons':d_up,
 'all_three_T_decreased':t_down==3,'all_three_D_increased':d_up==3,
 'remaining_research':'Both path-sum candidates, complete scientific review and final lifecycle/cleanup remain.',
 'limitations':'Historical selection window; only H7/H15/H20; F136days in2024; formal v5 old-label control not used for these causal paired differences.'}
write(BASE/'docs/horizon-result-verification.json',out)
print(json.dumps({'T_decreased':t_down,'D_increased':d_up,'out_of_horizons':3,'maxima':maxima},ensure_ascii=False),flush=True)
